type sourceFileMeta = taskfile.Metadata

// StageSourceFile 为每个输入建立 UUIDv4 工作目录，保留原文件名称与格式。
func StageSourceFile(in *task.CreateTaskInput) error {
	metaPath := filepath.Join(in.OutputDir, "source_meta.json")
	if data, err := os.ReadFile(metaPath); err == nil {
		var meta sourceFileMeta
		if json.Unmarshal(data, &meta) == nil && meta.StagedPath != "" {
			if _, statErr := os.Stat(meta.StagedPath); statErr == nil && filepath.Clean(in.InputPath) == filepath.Clean(meta.StagedPath) {
				in.InputPath = meta.StagedPath
				return nil
			}
		}
	}

	originalPath := in.InputPath
	origName := filepath.Base(originalPath)
	id := uuid.NewV4().String()
	workDir := filepath.Join(in.OutputDir, id)
	if err := os.Mkdir(workDir, 0755); err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			if err := os.RemoveAll(workDir); err != nil {
				slog.Error("清理未完成的工作副本失败", "path", workDir, "err", err)
			}
		}
	}()
	stagedName := id + strings.ToLower(filepath.Ext(originalPath))
	destPath := filepath.Join(workDir, stagedName)
	metaPath = filepath.Join(workDir, "source_meta.json")
	resultName := id + ".mp4"

	srcFile, err := os.Open(in.InputPath)
	if err != nil {
		return fmt.Errorf("读取原源文件失败: %w", err)
	}
	defer srcFile.Close()

	sourceInfo, err := srcFile.Stat()
	if err != nil {
		return fmt.Errorf("读取源文件信息失败: %w", err)
	}
	destInfo, statErr := os.Stat(destPath)
	if statErr != nil && !errors.Is(statErr, os.ErrNotExist) {
		return statErr
	}
	if destInfo == nil || !os.SameFile(sourceInfo, destInfo) {
		dstFile, err := os.OpenFile(destPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
		if err != nil {
			return fmt.Errorf("创建副本文件失败: %w", err)
		}
		_, copyErr := io.Copy(dstFile, srcFile)
		closeErr := dstFile.Close()
		if copyErr != nil {
			return fmt.Errorf("拷贝源文件副本失败: %w", copyErr)
		}
		if closeErr != nil {
			return fmt.Errorf("保存源文件副本失败: %w", closeErr)
		}
	}

	sourceSubtitle := strings.TrimSuffix(originalPath, filepath.Ext(originalPath)) + ".srt"
	if data, err := os.ReadFile(sourceSubtitle); err == nil {
		if err := os.WriteFile(filepath.Join(workDir, "src.srt"), data, 0644); err != nil {
			return fmt.Errorf("保存源字幕失败: %w", err)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("读取源字幕失败: %w", err)
	}

	meta := sourceFileMeta{
		LayoutVersion: 1,
		ResultName:    resultName,
		OriginalName:  origName,
		OriginalPath:  in.InputPath,
		StagedName:    stagedName,
		StagedPath:    destPath,
		CreatedAt:     time.Now(),
	}
	metaBytes, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return err
	}
	if err := os.WriteFile(metaPath, metaBytes, 0o644); err != nil {
		return fmt.Errorf("保存源文件信息失败: %w", err)
	}

	in.InputPath = destPath
	in.OutputDir = workDir
	committed = true
	return nil
}
